import heapq


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    ordered_names = names if name_order == "ascending" else names[::-1]
    roots = data["roots"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        options = [None]
        options.extend(row for row in packages[name]
                       if row["version"] not in blocked.get(name, [])
                       and (name not in pins or row["version"] == pins[name]))
        choices.append(options)

    best_vector = None
    best = None
    for assignment in product(*choices):
        selected = {name: row for name, row in zip(names, assignment)
                    if row is not None}
        if any(name not in selected or
               not bounds[0] <= selected[name]["version"] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        graph = {}
        valid = True
        for name, row in selected.items():
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            graph[name] = []
            for dep in deps:
                other = selected.get(dep["name"])
                if other is None or not dep["min"] <= other["version"] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph[name])
        if reachable != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in graph):
            continue

        vector = tuple(selected[n]["version"] if n in selected else -1
                       for n in ordered_names)
        if (best_vector is None or
                (vector > best_vector if preference == "maximum"
                 else vector < best_vector)):
            best_vector = vector
            best = {name: row["version"] for name, row in selected.items()}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def solve_ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"
    def rounded(num):
        return (num + 5000) // 10000 if half_up else num // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def solve_jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in options}):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = sorted((job["start"], job["end"]) for job in subset)
        active = []
        valid = True
        for start, end in events:
            while active and active[0] <= start:
                heapq.heappop(active)
            heapq.heappush(active, end)
            if len(active) > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        selected = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def solve_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            outcomes = [(edge["duration"], coupons)]
            if coupons:
                outcomes.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            new_mask = mask | bit.get(edge["v"], 0)
            for duration, left in outcomes:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                new_state = (edge["v"], new_mask, left)
                if arrival < distances.get(new_state, float("inf")):
                    distances[new_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], new_mask, left))
    return {"arrival": None}


